def exl(kind):
    out = []
    for j in EXJ:
        if not j[5].startswith(kind): continue
        sc = KN[j[4]] + (" PK" if kind == "PK" and j[4] == "Raúl" else "")
        out.append(f"{d_(j[1])} {KN[j[2]]}전 {j[3]}분 {sc}")
    return ", ".join(out)
def nex(kind): return sum(1 for j in EXJ if j[5].startswith(kind))
